export default "/* research.css — domain residue for com.ikenga.research.\n *\n * Only research-local classes live here. Kit primitives (.frame*, .ip-split*,\n * .split-*, .dense-row*, .btn*, .tag, .chip, .badge, .atelier-state*,\n * .nav-group*, .nav-item*, etc.) are consumed from app-kit-css.js — never\n * re-derived here.\n *\n * Inject order: tokens-css → app-kit-css → research-css (this file).\n * data-workspace=\"agents\" on <html> → teal tint for active nav + accents.\n *\n * Local vocabulary (screen-scoped — NOT in the kit, per screen doc §4):\n *   - .ux-dot.ux-*           next-action mode dot colours (confirm/silent/approve)\n *   - .next-chip / .stage-chip  next-action chip + type chip (screen residue,\n *                            same shape as content's residue)\n *   - .rs-persona-*          Personas view 2-up card grid (no kit equivalent)\n *   - .rs-source-table/*     Sources view monitored register (dense table)\n *   - .rs-source-status      freshness pill (fresh/signal/stale — semantic colour)\n *   - .rs-src-badge          source type badge\n *   - .rs-xdomain            cross-domain \"Hand to sales\" link badge\n *   - .rs-prog / .rs-prog-fill  persona Fit score bar\n *   - .rs-empty-cta          small inline CTA in the empty state\n */\n\n/* ── Reduced motion gate ── */\n@media (prefers-reduced-motion: reduce) {\n  .split-row { transition: none; }\n  .split-group-chev { transition: none; }\n  .atelier-spin { animation: none; }\n  .atelier-prog > span { animation: none; }\n}\n\n/* ── Next-action mode dot + chips (screen residue) ──────────────────────────── */\n/* The .ux-dot base shape lives in app-kit; the mode COLOURS are screen-scoped.\n   confirm → achievement (amber) · silent → fg-faint (muted) · approve → primary. */\n.ux-dot.ux-confirm  { background: var(--achievement); }\n.ux-dot.ux-silent   { background: var(--fg-faint); }\n.ux-dot.ux-approve  { background: var(--primary); }\n\n/* ── Personas view (2-up ICP card grid) ─────────────────────────────────────── */\n.rs-persona-wrap {\n  padding: var(--space-4);\n  overflow-y: auto;\n  height: 100%;\n}\n.rs-persona-head {\n  font-family: var(--font-display);\n  font-size: 15px;\n  font-weight: 500;\n  margin-bottom: var(--space-4);\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n}\n.rs-persona-head .sub {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  color: var(--fg-faint);\n  letter-spacing: .06em;\n  text-transform: uppercase;\n}\n.rs-persona-grid {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: var(--space-3);\n}\n.rs-persona-card {\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-md);\n  padding: var(--space-4);\n  background: var(--bg-base);\n  display: grid;\n  gap: 8px;\n  align-content: start;\n}\n.rs-persona-tag {\n  font-family: var(--font-mono);\n  font-size: 9px;\n  letter-spacing: .05em;\n  text-transform: uppercase;\n  color: var(--tint-fg-active, var(--primary));\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-pill);\n  padding: 2px 7px;\n  justify-self: start;\n}\n.rs-persona-name {\n  font-family: var(--font-display);\n  font-size: 16px;\n  font-weight: 500;\n}\n.rs-persona-desc {\n  font-size: var(--text-body-sm);\n  color: var(--fg-muted);\n  line-height: 1.5;\n}\n.rs-persona-attr {\n  display: flex;\n  justify-content: space-between;\n  font-size: var(--text-body-sm);\n  color: var(--fg-muted);\n  border-top: 1px solid var(--border-soft);\n  padding-top: 7px;\n}\n.rs-persona-attr b {\n  color: var(--fg);\n  font-weight: 500;\n}\n\n/* ── Persona Fit-score progress bar ─────────────────────────────────────────── */\n.rs-prog {\n  height: 6px;\n  border-radius: 3px;\n  background: var(--bg-sunken);\n  overflow: hidden;\n  margin-top: 4px;\n}\n.rs-prog-fill {\n  height: 100%;\n  background: linear-gradient(90deg, var(--primary-soft), var(--primary));\n  border-radius: 3px;\n}\n\n/* ── Sources view (monitored register, dense table) ─────────────────────────── */\n.rs-source-wrap {\n  padding: var(--space-4);\n  overflow-y: auto;\n  height: 100%;\n}\n.rs-source-kpis {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: var(--space-3);\n  margin-bottom: var(--space-4);\n}\n.rs-source-kpi {\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-md);\n  padding: var(--space-3) var(--space-4);\n  background: var(--bg-base);\n}\n.rs-kpi-k {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: .06em;\n  text-transform: uppercase;\n  color: var(--fg-faint);\n}\n.rs-kpi-v {\n  display: block;\n  font-family: var(--font-display);\n  font-size: 26px;\n  font-weight: 500;\n  margin-top: 4px;\n}\n.rs-kpi-sub {\n  display: block;\n  font-size: 11px;\n  color: var(--fg-muted);\n  margin-top: 2px;\n}\n.rs-source-head {\n  font-family: var(--font-display);\n  font-size: 15px;\n  font-weight: 500;\n  margin-bottom: var(--space-3);\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n}\n.rs-source-head .sub {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  color: var(--fg-faint);\n  letter-spacing: .06em;\n  text-transform: uppercase;\n}\n.rs-source-card {\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-md);\n  overflow: hidden;\n  background: var(--bg-base);\n}\n.rs-source-table {\n  width: 100%;\n  border-collapse: collapse;\n}\n.rs-source-table th {\n  text-align: left;\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: .06em;\n  text-transform: uppercase;\n  color: var(--fg-faint);\n  padding: 10px var(--space-4);\n  border-bottom: 1px solid var(--border-soft);\n  background: var(--bg-sunken);\n  font-weight: 400;\n}\n.rs-source-table td {\n  padding: 12px var(--space-4);\n  border-bottom: 1px solid var(--border-soft);\n  font-size: var(--text-body-sm);\n  color: var(--fg-muted);\n}\n.rs-source-table tr:last-child td { border-bottom: 0; }\n.rs-source-table .rs-src-name { color: var(--fg); font-weight: 500; }\n.rs-source-table tbody tr { cursor: pointer; transition: background var(--motion-fast) var(--ease-calm); }\n.rs-source-table tbody tr:hover { background: var(--bg-raised); }\n\n.rs-src-badge {\n  font-family: var(--font-mono);\n  font-size: 9px;\n  letter-spacing: .05em;\n  text-transform: uppercase;\n  padding: 2px 7px;\n  border-radius: var(--radius-pill);\n  border: 1px solid var(--border-soft);\n  color: var(--fg-faint);\n  white-space: nowrap;\n}\n\n/* Freshness pill — SEMANTIC colour (not decorative): fresh=live, signal=achievement, stale=danger. */\n.rs-source-status {\n  font-family: var(--font-mono);\n  font-size: 9px;\n  letter-spacing: .05em;\n  text-transform: uppercase;\n  padding: 2px 7px;\n  border-radius: var(--radius-pill);\n  border: 1px solid var(--border-soft);\n  color: var(--fg-faint);\n  white-space: nowrap;\n}\n.rs-source-status.is-fresh  { color: var(--live);        border-color: var(--live-soft); }\n.rs-source-status.is-signal { color: var(--achievement); border-color: var(--achievement-soft); }\n.rs-source-status.is-stale  { color: var(--danger);      border-color: var(--danger-soft); }\n\n/* ── Cross-domain \"Hand to sales\" link badge ───────────────────────────────── */\n.rs-xdomain {\n  display: inline-flex;\n  align-items: center;\n  gap: 3px;\n  margin-left: 6px;\n  font-family: var(--font-mono);\n  font-size: 9px;\n  letter-spacing: .04em;\n  padding: 1px 6px;\n  border-radius: var(--radius-pill);\n  color: var(--tint-fg-active, var(--primary));\n  border: 1px solid var(--border-soft);\n  background: var(--bg-sunken);\n}\n\n/* ── Empty-state inline CTA ─────────────────────────────────────────────────── */\n.rs-empty-cta { margin-top: 8px; }\n"
